package com.bytbeat.mpctrainer

import android.content.Intent
import android.graphics.Color
import android.media.AudioAttributes
import android.media.SoundPool
import android.net.Uri
import android.os.*
import android.provider.OpenableColumns
import android.view.*
import android.widget.*
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream
import kotlin.math.roundToLong

class MainActivity : AppCompatActivity() {
 data class PadSample(val soundId:Int,val name:String,val path:String)
 data class NoteEvent(val bank:Int,val pad:Int,var tick:Long,val track:Int,val velocity:Int=100)
 private lateinit var pool:SoundPool
 private val pads=Array(4){arrayOfNulls<PadSample>(16)};private val events=mutableListOf<NoteEvent>();private val padButtons=mutableListOf<Button>();private val mute=BooleanArray(4);private val h=Handler(Looper.getMainLooper())
 private var bank=0;private var pad=0;private var track=0;private var bpm=90;private var bars=2;private var tc=16;private var swing=50;private var rec=false;private var overdub=false;private var playing=false;private var noteRepeat=false;private var fullLevel=false;private var levels16=false;private var levelsBank=0;private var levelsPad=0;private var start=0L;private var last=-1L;private var pendingUri:Uri?=null;private var pendingDisplayName="";private var learn=false;private var lesson=0;private var stepPage=0
 private lateinit var top:TextView;private lateinit var pos:TextView;private lateinit var info:TextView;private lateinit var learnText:TextView
 override fun onCreate(b:Bundle?){super.onCreate(b);pool=SoundPool.Builder().setMaxStreams(24).setAudioAttributes(AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_GAME).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build()).build();loadAssignments();loadProject();setContentView(build());refresh();screen();lessonText()}
 private fun button(s:String,f:(View)->Unit)=Button(this).apply{text=s;textSize=8.5f;setOnClickListener(f)}
 private fun row(vararg b:Button)=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;b.forEach{addView(it,LinearLayout.LayoutParams(0,46,1f))}}
 private fun lcd(size:Float,bold:Boolean)=TextView(this).apply{textSize=size;setTextColor(Color.rgb(207,232,193));if(bold)setTypeface(typeface,1)}
 private fun build():View{val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(10,8,10,8);setBackgroundColor(Color.rgb(216,210,195))};root.addView(TextView(this).apply{text="MPC TRAINER • LIVE III / MPC 3";textSize=16f;setTypeface(typeface,1);setTextColor(Color.rgb(38,37,33))},LinearLayout.LayoutParams(-1,34));val display=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(12,7,12,7);setBackgroundColor(Color.rgb(53,68,60))};top=lcd(14f,true);pos=lcd(11f,true);info=lcd(10.5f,false);display.addView(top);display.addView(pos);display.addView(info);root.addView(display,LinearLayout.LayoutParams(-1,96));learnText=TextView(this).apply{textSize=11f;setPadding(8,5,8,5);setTextColor(Color.rgb(38,37,33));setBackgroundColor(Color.rgb(232,224,202));visibility=View.GONE};root.addView(learnText);root.addView(row(button("MAIN"){info.text="MAIN • SEQUENCE / TRACK";action("main")},button("BROWSE"){action("browse");openSample()},button("SAMPLE EDIT"){info.text="SAMPLE EDIT • next core module"},button("LEARN"){learn=!learn;learnText.visibility=if(learn)View.VISIBLE else View.GONE;lessonText()}));root.addView(row(*listOf("A","B","C","D").mapIndexed{i,n->button("BANK $n"){bank=i;refresh();screen()}}.toTypedArray()));val grid=GridLayout(this).apply{columnCount=4;rowCount=4;setPadding(2,2,2,2)};repeat(16){i->val b=Button(this).apply{textSize=8.5f;gravity=Gravity.CENTER;setTextColor(Color.WHITE);setBackgroundColor(Color.rgb(58,57,53));setOnTouchListener{_,e->when(e.action){MotionEvent.ACTION_DOWN->{pad=i;hit(bank,i,true);action("pad") ;if(noteRepeat)repeatStart()};MotionEvent.ACTION_UP,MotionEvent.ACTION_CANCEL->repeatStop()};refresh();true}};padButtons+=b;grid.addView(b,GridLayout.LayoutParams().apply{width=0;height=80;columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);setMargins(3,3,3,3)})};root.addView(grid,LinearLayout.LayoutParams(-1,0,1f));root.addView(row(button("NOTE REPEAT"){noteRepeat=!noteRepeat;info.text="NOTE REPEAT ${if(noteRepeat)"ON" else "OFF"}"},button("FULL LEVEL"){fullLevel=!fullLevel;info.text="FULL LEVEL ${if(fullLevel)"127" else "OFF"}"},button("16 LEVELS"){if(!levels16){levelsBank=bank;levelsPad=pad;levels16=true;info.text="16 LEVELS • ${'A'+levelsBank}${levelsPad+1} • VELOCITY"}else{levels16=false;info.text="16 LEVELS OFF"};refresh()},button("STEP SEQ"){showSteps()}));root.addView(row(button("PREV"){stepPage=(stepPage+bars-1)%bars;info.text="STEP BAR ${stepPage+1}"},button("SET"){showStepModes()},button("NEXT"){stepPage=(stepPage+1)%bars;info.text="STEP BAR ${stepPage+1}"},button("TC / SWING"){tc=when(tc){8->16;16->32;else->8};swing=when(swing){50->54;54->58;else->50};saveProject();info.text="TC 1/$tc • SWING $swing%"}));root.addView(row(button("TRACK −"){track=(track+3)%4;screen()},button("TRACK +"){track=(track+1)%4;screen()},button("TRACK MUTE"){mute[track]=!mute[track];saveProject();screen()},button("MENU"){info.text="MENU • MPC 3"}));root.addView(row(button("REC"){record(false);action("record")},button("OVERDUB"){record(true);action("overdub")},button("STOP"){stop();action("stop")},button("PLAY"){play();action("play")}));return root}
 private fun showStepModes(){AlertDialog.Builder(this).setTitle("SET • STEP BUTTON MODES").setItems(arrayOf("1 Drum Seq","2 Note Seq","3 Step Edit","4 Note Length","5 Last Step","6 Automation","9 Track Select","10 Track Arm","11 Track Mute","12 Pad Mute","13 Next Seq")){_,which->info.text="STEP MODE • ${which+1} • training reference"}.show()}
 private fun openSample(){startActivityForResult(Intent(Intent.ACTION_OPEN_DOCUMENT).apply{addCategory(Intent.CATEGORY_OPENABLE);type="audio/*"},900)}
 private fun ppq()=96L;private fun loop()=bars*4*ppq();private fun mpt()=60000.0/bpm/ppq();private fun tick()=((SystemClock.elapsedRealtime()-start)/mpt()).toLong()%loop();private fun quant(raw:Long):Long{val step=(ppq()*4/tc).coerceAtLeast(1);var x=(raw.toDouble()/step).roundToLong()*step;if((x/step)%2L==1L&&swing>50)x+=((step*(swing-50))/50.0).roundToLong();return x%loop()}
 private fun levelVelocity(index:Int)=(((index+1)*127f/16f).roundToLong().toInt()).coerceIn(1,127)
 private fun playPad(b:Int,p:Int,velocity:Int){if(mute[track])return;pads[b][p]?.let{val v=velocity.coerceIn(1,127)/127f;pool.play(it.soundId,v,v,1,0,1f)}}
 private fun hit(b:Int,p:Int,user:Boolean){val sb=if(levels16)levelsBank else b;val sp=if(levels16)levelsPad else p;val vel=when{levels16->levelVelocity(p);fullLevel->127;else->100};playPad(sb,sp,vel);if(user&&rec&&playing){events+=NoteEvent(sb,sp,quant(tick()),track,vel);saveProject();info.text="REC • T${track+1} • ${'A'+sb}${sp+1} • VEL $vel"}else if(user)info.text="${'A'+sb}${sp+1} • ${pads[sb][sp]?.name?:"EMPTY"} • VEL $vel"}
 private val runner=object:Runnable{override fun run(){if(!playing)return;val t=tick();events.filter{!mute[it.track]&&dist(it.tick,t,loop())<=1}.forEach{e->if(e.tick!=last)pads[e.bank][e.pad]?.let{val v=e.velocity.coerceIn(1,127)/127f;pool.play(it.soundId,v,v,1,0,1f)}};last=t;screen();h.postDelayed(this,2)}};private fun dist(a:Long,b:Long,l:Long):Long{val d=kotlin.math.abs(a-b);return minOf(d,l-d)}
 private fun play(){if(playing)return;playing=true;rec=false;start=SystemClock.elapsedRealtime();last=-1;h.post(runner);info.text="PLAY"};private fun record(od:Boolean){if(!od)events.removeAll{it.track==track};playing=true;rec=true;overdub=od;start=SystemClock.elapsedRealtime();last=-1;h.removeCallbacks(runner);h.post(runner);saveProject();info.text=if(od)"OVERDUB • TRACK ${track+1}" else "REC • TRACK ${track+1}"};private fun stop(){playing=false;rec=false;overdub=false;h.removeCallbacks(runner);repeatStop();last=-1;saveProject();info.text="STOP • ${events.size} EVENTS";screen()}
 private val repeater=object:Runnable{override fun run(){if(noteRepeat){hit(bank,pad,true);h.postDelayed(this,(60000.0/bpm*(4.0/tc)).toLong().coerceAtLeast(20))}}};private fun repeatStart(){h.removeCallbacks(repeater);h.postDelayed(repeater,(60000.0/bpm*(4.0/tc)).toLong())};private fun repeatStop(){h.removeCallbacks(repeater)}
 private fun showSteps(){val wrap=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(10,10,10,10)};val pageText=TextView(this).apply{textSize=14f;gravity=Gravity.CENTER};val box=GridLayout(this).apply{columnCount=4};val bs=ArrayList<Button>();repeat(16){val b=Button(this);bs+=b;box.addView(b,GridLayout.LayoutParams().apply{width=150;height=102})};fun redraw(){pageText.text="BAR ${stepPage+1} / $bars • ${'A'+bank}${pad+1}";val st=ppq()/4;bs.forEachIndexed{i,b->val t=stepPage*4*ppq()+i*st;val e=events.firstOrNull{it.track==track&&it.bank==bank&&it.pad==pad&&it.tick==t};b.text="${i+1}\n${if(e!=null)"● ${e.velocity}" else "○"}";b.setOnClickListener{val at=events.indexOfFirst{x->x.track==track&&x.bank==bank&&x.pad==pad&&x.tick==t};if(at>=0)events.removeAt(at)else events+=NoteEvent(bank,pad,t,track,127);saveProject();redraw();action("step")}}};wrap.addView(pageText);wrap.addView(box);wrap.addView(row(button("◀ PREV"){stepPage=(stepPage+bars-1)%bars;redraw()},button("NEXT ▶"){stepPage=(stepPage+1)%bars;redraw()}));redraw();AlertDialog.Builder(this).setTitle("DRUM SEQ • 16 STEP BUTTONS").setView(wrap).setPositiveButton("DONE",null).show()}
 private fun lessonText(){if(!learn)return;learnText.text=when(lesson){0->"LESSON 1 • LOAD A SOUND\nPress BROWSE, choose a drum sample, preview it and LOAD TO PAD. The lesson advances only after a pad really has a sample.";1->"LESSON 2 • AUDITION THE PAD\nHit the loaded pad. Learn the basic Browser → Pad workflow.";2->"LESSON 3 • RECORD\nPress REC, play a simple pattern on your loaded pad, then STOP. The trainer checks that note events were actually recorded.";3->"LESSON 4 • STEP SEQUENCER\nOpen STEP SEQ and add at least one step. Use PREV/NEXT to move through bars, like Live III hardware Step Buttons.";else->"FOUNDATION COMPLETE • Browser → Pads → Record → Step Sequencer. More guided MPC lessons unlock as the real functions are implemented."}}
 private fun action(a:String){if(!learn)return;val old=lesson;when(lesson){0->if(a=="loaded"&&pads.flatten().any{it!=null})lesson=1;1->if(a=="pad"&&pads[bank][pad]!=null)lesson=2;2->if(a=="stop"&&events.isNotEmpty())lesson=3;3->if(a=="step"&&events.isNotEmpty())lesson=4};if(old!=lesson){getSharedPreferences("mpc",MODE_PRIVATE).edit().putInt("lesson",lesson).apply();lessonText();Toast.makeText(this,"Lesson ${old+1} complete",Toast.LENGTH_SHORT).show()}}
 private fun screen(){val t=if(playing)tick()else 0;val bar=t/(ppq()*4)+1;val beat=t/ppq()%4+1;val sub=t%ppq();top.text="SEQ 01 • TRACK ${track+1} • BANK ${'A'+bank} • PAD ${pad+1}${if(mute[track])" • MUTE" else ""}";pos.text="$bpm BPM • $bars BARS • ${bar.toString().padStart(3,'0')}:${beat.toString().padStart(2,'0')}:${sub.toString().padStart(2,'0')}"}
 private fun refresh(){padButtons.forEachIndexed{i,b->val s=if(levels16)pads[levelsBank][levelsPad] else pads[bank][i];b.text=if(levels16)"${i+1}\nVEL ${levelVelocity(i)}" else if(s==null)"${i+1}\nEMPTY" else "${i+1}\n${s.name.take(8)}";b.alpha=if(i==pad)1f else .84f}}
 @Deprecated("Deprecated in Java") override fun onActivityResult(r:Int,c:Int,d:Intent?){super.onActivityResult(r,c,d);if(r==900&&c==RESULT_OK){val u=d?.data?:return;pendingUri=u;pendingDisplayName=displayName(u);val fd=contentResolver.openFileDescriptor(u,"r")?:return;pool.setOnLoadCompleteListener{_,id,status->if(status==0)pool.play(id,.8f,.8f,1,0,1f)};val preview=pool.load(fd.fileDescriptor,0,fd.statSize,1);fd.close();AlertDialog.Builder(this).setTitle("BROWSER • ${pendingDisplayName.substringBeforeLast('.')}").setMessage("Preview sample. Load to BANK ${'A'+bank} PAD ${pad+1}?").setNegativeButton("CANCEL",null).setNeutralButton("PREVIEW"){_,_->pool.play(preview,.8f,.8f,1,0,1f)}.setPositiveButton("LOAD TO PAD"){_,_->assignPending()}.show()}}
 private fun assignPending(){val u=pendingUri?:return;val dir=File(filesDir,"samples").apply{mkdirs()};val original=if(pendingDisplayName.isBlank())"sample.wav" else pendingDisplayName;val f=File(dir,"${System.currentTimeMillis()}_${original.replace(Regex("[^A-Za-z0-9._-]"),"_")}");contentResolver.openInputStream(u)?.use{input->FileOutputStream(f).use{out->input.copyTo(out)}};pads[bank][pad]=PadSample(pool.load(f.absolutePath,1),original.substringBeforeLast('.'),f.absolutePath);saveAssignments();info.text="BROWSER • ${original.substringBeforeLast('.')} → ${'A'+bank}${pad+1}";refresh();action("loaded")}
 private fun saveAssignments(){val root=JSONObject();for(b in 0..3)for(p in 0..15)pads[b][p]?.let{s->root.put("$b:$p",JSONObject().put("name",s.name).put("path",s.path))};getSharedPreferences("mpc",MODE_PRIVATE).edit().putString("pads",root.toString()).apply()}
 private fun loadAssignments(){val raw=getSharedPreferences("mpc",MODE_PRIVATE).getString("pads",null)?:return;try{val root=JSONObject(raw);val keys=root.keys();while(keys.hasNext()){val k=keys.next();val q=k.split(":");if(q.size!=2)continue;val b=q[0].toInt();val p=q[1].toInt();val o=root.getJSONObject(k);val path=o.getString("path");if(File(path).exists())pads[b][p]=PadSample(pool.load(path,1),o.getString("name"),path)}}catch(_:Exception){}}
 private fun saveProject(){val a=JSONArray();events.forEach{e->a.put(JSONObject().put("bank",e.bank).put("pad",e.pad).put("tick",e.tick).put("track",e.track).put("velocity",e.velocity))};val m=JSONArray();mute.forEach{m.put(it)};val o=JSONObject().put("events",a).put("bpm",bpm).put("bars",bars).put("tc",tc).put("swing",swing).put("mute",m);getSharedPreferences("mpc",MODE_PRIVATE).edit().putString("project",o.toString()).apply()}
 private fun loadProject(){val sp=getSharedPreferences("mpc",MODE_PRIVATE);lesson=sp.getInt("lesson",0);val raw=sp.getString("project",null)?:return;try{val o=JSONObject(raw);bpm=o.optInt("bpm",90);bars=o.optInt("bars",2).coerceAtLeast(1);tc=o.optInt("tc",16);swing=o.optInt("swing",50);val a=o.optJSONArray("events")?:JSONArray();for(i in 0 until a.length()){val e=a.getJSONObject(i);events+=NoteEvent(e.getInt("bank"),e.getInt("pad"),e.getLong("tick"),e.getInt("track"),e.optInt("velocity",100))};val m=o.optJSONArray("mute");if(m!=null)for(i in 0 until minOf(4,m.length()))mute[i]=m.optBoolean(i,false)}catch(_:Exception){}}
 private fun displayName(u:Uri):String{contentResolver.query(u,null,null,null,null)?.use{c->val i=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(i>=0&&c.moveToFirst())return c.getString(i)};return "sample.wav"}
 override fun onDestroy(){h.removeCallbacksAndMessages(null);pool.release();super.onDestroy()}
}
